fn parse_port(text: &str) -> Option<u16> {
    text.parse::<u16>().ok().filter(|p| *p != 0)
}

fn endpoint(config: &Config) -> Option<String> {
    let host = config.host.as_deref()?;        // ? early-returns None
    Some(format!("{host}:{}", parse_port(&config.port)?))
}

